import * as React from "react"
import Outcome from "../../components/Outcome"
import Seo from "../../components/Seo"

/**
 * Back from a completed purchase — MTC-FCS-008.
 *
 * Deliberately narrower than /website/success: this screen confirms a PAYMENT,
 * and says nothing about a site being live. The two are different facts, and
 * the one thing worse than a slow deploy is a page that says you are online
 * when you are not.
 */
const PurchaseSuccessPage = () => (
  <Outcome
    tone="success"
    title="Payment received"
    lead="Thanks — your hosting subscription is active and a receipt is on its way to your email."
    points={[
      "Your receipt has the link to manage or cancel the subscription",
      "Your website goes live from the builder, where you left it",
      "Nothing else to pay — hosting is the only charge",
    ]}
    primary={{ href: "/website-builder", label: "Go to my website" }}
    secondary={{ href: "/account", label: "View my account" }}
  />
)

export const Head = () => <Seo title="Payment received" />

export default PurchaseSuccessPage
